from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    """Return 0 for even x and 1 for odd x."""
    return x % 2


def parities(xs: list[int], workers: int = 4) -> list[int]:
    """Return the parity of each element of xs, computed in a thread pool.

    The result is in the same order as the input. The output must not
    depend on the value of ``workers``.
    """
    with ThreadPoolExecutor(max_workers=workers) as executor:
        return list(executor.map(parity, xs))


@pytest.mark.parametrize("workers", [1, 2, 4, 16])
def test_parities_basic(workers: int) -> None:
    assert parities([0, 1, 2, 3, 4], workers=workers) == [0, 1, 0, 1, 0]


@pytest.mark.parametrize("workers", [1, 3, 8])
def test_parities_preserves_order(workers: int) -> None:
    xs = list(range(100, 0, -1))
    assert parities(xs, workers=workers) == [x % 2 for x in xs]


@pytest.mark.parametrize("workers", [1, 5])
def test_parities_negative_numbers(workers: int) -> None:
    assert parities([-3, -2, -1, 0], workers=workers) == [1, 0, 1, 0]


@pytest.mark.parametrize("workers", [1, 4])
def test_parities_empty(workers: int) -> None:
    assert parities([], workers=workers) == []


def test_parities_independent_of_worker_count() -> None:
    xs = [7, 12, -5, 0, 99, 1024, -8, 3]
    results = [parities(xs, workers=w) for w in (1, 2, 4, 9)]
    assert all(r == results[0] for r in results)
